<section class="container narrow section"><h1>Create your account</h1><?php if (!empty($errors)): ?><div class="flash flash-error"><?php foreach ($errors as $field => $msgs): foreach ($msgs as $msg): ?><div><?= e($msg) ?></div><?php endforeach; endforeach; ?></div><?php endif; ?><form action="/register" method="post" class="stack-form card"><?= \App\Util\Csrf::field() ?><label>Username <?php if (!empty($errors['username'])): ?><span class="field-error"><?= e($errors['username'][0]) ?></span><?php endif; ?><input type="text" name="username" value="<?= e(old('username')) ?>" required></label><label>Real name <?php if (!empty($errors['real_name'])): ?><span class="field-error"><?= e($errors['real_name'][0]) ?></span><?php endif; ?><input type="text" name="real_name" value="<?= e(old('real_name')) ?>" required></label><label>Email <?php if (!empty($errors['email'])): ?><span class="field-error"><?= e($errors['email'][0]) ?></span><?php endif; ?><input type="email" name="email" value="<?= e(old('email')) ?>" required></label><label>Password <?php if (!empty($errors['password'])): ?><span class="field-error"><?= e($errors['password'][0]) ?></span><?php endif; ?><input type="password" name="password" required></label><button class="button" type="submit">Register</button><p class="muted">Your real name is stored privately and is never shown publicly.</p></form></section>
